-- ============================================================
-- نتائج اللائحة المحلية (تقديرية) — دائرة تطوان، انتخابات 23 شتنبر 2026
-- طلب علي (25 شتنبر 2026): صفحة نتائج مفصّلة بالمكاتب/المدارس مربوطة
-- بـpolling_stations + حالة تغطية المراقبين. المصدر: ملف
-- TETOUAN_LOCAL_LIST_RESULTS_PROXY_2026_v1.0.xlsx الذي رفعه علي —
-- بيانات تقديرية/تحليلية مبنية على محضر اللائحة الجهوية (وليست
-- نتائج رسمية للائحة المحلية)، راجع حقل status/note لكل صف.
-- ============================================================

create table if not exists public.election_results (
  id uuid primary key default gen_random_uuid(),
  office_number integer not null unique,
  center_name text not null,
  registered_voters integer,
  voters_count integer,
  void_votes integer,
  valid_votes integer,
  party_votes jsonb not null default '{}'::jsonb,
  total_lists integer,
  diff_check integer,
  status text,
  created_at timestamptz not null default now()
);
create index if not exists election_results_center_idx on public.election_results (center_name);

create table if not exists public.election_results_summary (
  id uuid primary key default gen_random_uuid(),
  list_rank integer not null,
  list_name text not null,
  total_votes integer not null,
  pct_valid numeric,
  link_status text,
  note text,
  is_our_list boolean not null default false,
  created_at timestamptz not null default now()
);

alter table public.election_results enable row level security;
drop policy if exists "authenticated read election_results" on public.election_results;
create policy "authenticated read election_results" on public.election_results
  for select using (auth.role() = 'authenticated');
drop policy if exists "editors write election_results" on public.election_results;
create policy "editors write election_results" on public.election_results
  for all using (public.is_editor_or_admin());

alter table public.election_results_summary enable row level security;
drop policy if exists "authenticated read election_results_summary" on public.election_results_summary;
create policy "authenticated read election_results_summary" on public.election_results_summary
  for select using (auth.role() = 'authenticated');
drop policy if exists "editors write election_results_summary" on public.election_results_summary;
create policy "editors write election_results_summary" on public.election_results_summary
  for all using (public.is_editor_or_admin());

-- تفريغ قبل إعادة الإدخال (السكريبت آمن للتشغيل أكثر من مرة)
delete from public.election_results;
delete from public.election_results_summary;



